<script setup lang="ts">
import {stages,time,qualities} from '../measurements/model'
defineProps<{sample:any;review:any;writable:boolean}>()
const number=(v:any)=>v===null||v===undefined?'未记录':Number(v).toLocaleString('zh-CN',{maximumSignificantDigits:9})
</script>
<template><section data-testid="sample-research-review">
<div class="review-actions"><router-link v-if="writable" :to="{path:'/imports',query:{sample_id:sample.sample_id}}"><el-button type="primary">导入该样品数据</el-button></router-link><router-link :to="{path:'/analysis',query:{sample_id:sample.sample_id}}"><el-button>点级图表与明确配对</el-button></router-link><router-link v-if="writable" :to="{path:'/processes',query:{create:'1',sample_id:sample.sample_id,batch_id:sample.batch_id}}"><el-button>继续实验</el-button></router-link></div>
<h3>测量结果摘要</h3><p class="field-hint">可用点为有膜厚且未标异常的点；原始均值保留，不按此计数自动重算。</p><div data-testid="measurement-summary" class="measurement-reading-grid"><article v-for="m in review?.measurements??[]" :key="m.measurement_id" class="measurement-reading"><h4>{{stages[m.stage]||m.stage}} <span v-if="!m.is_current">已被重测取代</span></h4><p>原始平均膜厚 <strong>{{number(m.thickness_mean_nm)}} <small>nm</small></strong></p><p>可用膜厚点 {{m.valid_point_count??'未记录'}} / 总点数 {{m.point_count??'未记录'}} · 质量 {{qualities[m.quality_flag]||m.quality_flag}}</p><p v-if="m.mse_mean!=null">MSE {{number(m.mse_mean)}}（拟合质量）</p><p>{{m.model_name||'模型未记录'}}</p><div class="measurement-reading-links"><router-link :to="{path:'/measurements',query:{id:m.measurement_id}}">测量详情</router-link><router-link v-if="m.source_file_id" :to="{path:'/source-files',query:{id:m.source_file_id}}">原始文件</router-link></div></article></div><h3>椭偏表观变化 / apparent</h3><p class="field-hint">表观减薄量 = 处理前均值 − 处理后均值；正值减薄，负值增厚。每循环表观刻蚀量仅使用明确处理间隔内的逐片实际循环数。</p><p v-if="!review?.results?.length" class="field-hint">无法计算：尚无已确认的前后测量对。不会按文件名、时期或设备总循环数猜测。</p>
<article v-for="r in review?.results??[]" :key="r.after_measurement_id" class="review-result"><strong>{{ r.before_code||'前测未确认' }} → {{ r.after_code }}</strong><p v-if="r.reason" class="field-hint">无法计算：{{ r.reason }}</p><template v-else><p>前 {{ number(r.before_mean_nm) }} nm → 后 {{ number(r.after_mean_nm) }} nm；表观减薄 {{ number(r.thinning_nm) }} nm</p><p v-if="r.epc_nm_per_cycle!==null">本次有效 {{ r.effective_cycles }} cycles · 每循环表观刻蚀量 {{ number(r.epc_nm_per_cycle) }} nm/cycle</p><p v-else class="field-hint">每循环表观刻蚀量无法计算：{{ r.epc_reason }}</p></template><details><summary>计算依据、质量规则与来源</summary><p>{{ r.quality_rule }}</p><p>{{ r.interpretation }}</p><p>函数 app.sample_review.review · {{ r.version }}；点级计算 {{ r.analysis_version }}</p><pre>{{ JSON.stringify(r.sources??[],null,2) }}</pre></details></article>
<details><summary>测量详情：真实测点、模型与原始文件</summary><h3>测量历史</h3><p v-if="!review?.measurements?.length" class="field-hint">暂无测量；导入后刷新本详情即可查看。</p>
<el-table v-else :data="review.measurements" max-height="420" data-testid="sample-measurements"><el-table-column label="测量 / 阶段" min-width="150"><template #default="{row}"><router-link :to="{path:'/measurements',query:{id:row.measurement_id}}">{{ row.measurement_code }}</router-link><div>{{ stages[row.stage]||row.stage }} · {{ row.is_current?'当前':'已被重测取代' }}</div></template></el-table-column><el-table-column label="测量时间" min-width="160"><template #default="{row}">{{ time(row.measured_at) }}</template></el-table-column><el-table-column label="均值 / nm" min-width="115"><template #default="{row}">{{ number(row.thickness_mean_nm) }}</template></el-table-column><el-table-column prop="point_count" label="测点数" width="85"/><el-table-column label="MSE / 质量" min-width="120"><template #default="{row}">{{ number(row.mse_mean) }} / {{ row.quality_flag }}</template></el-table-column><el-table-column label="光学模型" min-width="140"><template #default="{row}">{{ row.model_name }}<div class="field-hint">{{ row.model_parameters.join('、')||'参数定义未记录' }}</div></template></el-table-column><el-table-column label="图与来源" min-width="145"><template #default="{row}"><router-link :to="{path:'/analysis',query:{sample_id:sample.sample_id,measurement_id:row.measurement_id}}">原始图 </router-link><router-link v-if="row.source_file_id" :to="{path:'/source-files',query:{id:row.source_file_id}}"> 原件</router-link></template></el-table-column></el-table>
</details></section></template>
<style scoped>.measurement-reading-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,230px),1fr));gap:14px;margin:16px 0 24px}.measurement-reading{padding:16px 18px;background:#edf3f6;border:1px solid var(--line);border-radius:10px;box-shadow:inset 2px 2px 6px #d4dfe650,inset -2px -2px 6px #fff}.measurement-reading h4{margin:0 0 10px;font-size:13px}.measurement-reading h4 span{color:var(--muted);font-size:12px;font-weight:400}.measurement-reading p{font-size:12px;line-height:1.8;margin:5px 0;color:var(--muted)}.measurement-reading strong{font-size:25px;font-weight:600;color:var(--ink);font-variant-numeric:tabular-nums}.measurement-reading small{font-size:12px;font-weight:400}.measurement-reading-links{display:flex;gap:16px;margin-top:10px}.measurement-reading-links a{color:#086d79;font-size:13px;padding:6px 0}.review-actions{display:flex;flex-wrap:wrap;gap:8px;margin:16px 0}.review-result{border-top:1px solid var(--line);padding:14px 0}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}summary{cursor:pointer}</style>
